function applyCalculation(value, callback) {
  return callback(value);
}
function double(number) {
  return number * 2;
}
function runDouble(value) {
  return applyCalculation(value, double);
}

function calculateWith(a, b, operation) {
  return operation(a, b);
}
function add(x, y) {
  return x + y;
}
function multiply(x, y) {
  return x * y;
}
function runByMode(a, b, mode) {
  if (mode === 'add') {
    return calculateWith(a, b, add);
  }
  return calculateWith(a, b, multiply);
}
